pm.test("Quota should be enforced", function () {
    pm.expect(pm.response.code).to.be.oneOf([429, 403]);
});

const response = pm.response.json();
const error = response.error || {};

const resetAt = error.resetAt || response.resetAt;

pm.test("resetAt should be present", function () {
    pm.expect(resetAt, "resetAt is missing").to.exist;
});

if (resetAt) {

    // ==========================================
    // 1. Current quota exhausted time
    // ==========================================

    const exhaustedAt = new Date();

    // ==========================================
    // 2. Reset timestamp from API
    // ==========================================

    const resetTime = new Date(resetAt);

    // ==========================================
    // 3. Calculate remaining time
    // ==========================================

    const remainingMs = resetTime.getTime() - exhaustedAt.getTime();

    const remainingMinutes = remainingMs / (1000 * 60);
    const remainingHours = remainingMinutes / 60;

    // ==========================================
    // 4. Calculate total reset window
    // ==========================================
    //
    // We save the timestamp when quota became
    // exhausted and compare it with resetAt.
    //

    const windowHours = remainingHours;
    const windowMinutes = remainingMinutes;

    // ==========================================
    // 5. Save values to Postman Environment
    // ==========================================

    pm.environment.set(
        "free_quota_exhausted_at",
        exhaustedAt.toISOString()
    );

    pm.environment.set(
        "free_quota_reset_at",
        resetTime.toISOString()
    );

    pm.environment.set(
        "free_quota_remaining_minutes",
        remainingMinutes.toFixed(2)
    );

    pm.environment.set(
        "free_quota_remaining_hours",
        remainingHours.toFixed(2)
    );

    pm.environment.set(
        "free_quota_window_minutes",
        windowMinutes.toFixed(2)
    );

    pm.environment.set(
        "free_quota_window_hours",
        windowHours.toFixed(2)
    );

    // ==========================================
    // 6. Console output
    // ==========================================

    console.log("========== FREE QUOTA RESET ==========");
    console.log("Quota Exhausted At:", exhaustedAt.toISOString());
    console.log("Reset At:", resetTime.toISOString());
    console.log(
        "Remaining Minutes:",
        remainingMinutes.toFixed(2)
    );
    console.log(
        "Remaining Hours:",
        remainingHours.toFixed(2)
    );
    console.log(
        "Calculated Window Hours:",
        windowHours.toFixed(2)
    );
    console.log("=======================================");
}

// ==========================================
// 7. Save API quota information
// ==========================================

if (error.message) {
    pm.environment.set(
        "free_quota_message",
        error.message
    );
}

if (error.code) {
    pm.environment.set(
        "free_quota_error_code",
        error.code
    );
}

// ==========================================
// 8. Validate expected error
// ==========================================

pm.test("Response should indicate rate limit", function () {

    pm.expect(
        error.code ||
        error.type ||
        error.message
    ).to.exist;
});

